<div class="page-head"><div><a href="/app/contratti" class="text-decoration-none">← Torna ai contratti</a><p class="text-uppercase small fw-semibold text-success mt-3 mb-1">Contratto <?= e($contract['numero']) ?></p><h1 class="h2 mb-1"><?= e($contract['titolo']) ?></h1><p class="text-secondary mb-0">Stato: <?= e(ucfirst(str_replace('_',' ',$contract['stato']))) ?> · <?= e(date('d/m/Y',strtotime($contract['data_inizio']))) ?><?= $contract['data_fine']?' – '.e(date('d/m/Y',strtotime($contract['data_fine']))):'' ?></p></div></div>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="row"><div class="col-md-4"><small class="text-secondary">Cliente</small><p class="fw-semibold"><?= e($contract['cliente']) ?></p></div><div class="col-md-4"><small class="text-secondary">Sede</small><p class="fw-semibold"><?= e($contract['sede_nome']?:'Non indicata') ?></p></div><div class="col-md-4"><small class="text-secondary">Visite completate</small><p class="fw-semibold"><?= count(array_filter($visite,fn($v)=>$v['stato']==='completata')) ?> di <?= (int)$contract['totale_visite'] ?></p></div><div class="col-md-4"><small class="text-secondary">Piano</small><p class="fw-semibold mb-0"><?= e($contract['frequenza']) ?> · <?= (int)$contract['totale_visite'] ?> visite</p></div></div><div class="progress" role="progressbar" aria-label="Avanzamento visite" aria-valuenow="<?= count(array_filter($visite,fn($v)=>$v['stato']==='completata')) ?>" aria-valuemin="0" aria-valuemax="<?= (int)$contract['totale_visite'] ?>"><div class="progress-bar bg-success" style="width:<?= $contract['totale_visite']?min(100,count(array_filter($visite,fn($v)=>$v['stato']==='completata'))/(int)$contract['totale_visite']*100):0 ?>%"></div></div><div class="mt-3"><strong>Servizi inclusi:</strong><br><?= nl2br(e($contract['servizi']?:'—')) ?></div></div></div>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h4 mb-1">Visite previste</h2><p class="text-secondary mb-0">Modificare una data aggiorna la visita e ne conserva la cronologia.</p></div></div>
<div class="table-wrap"><table class="table table-hover align-middle"><thead><tr><th>#</th><th>Data pianificata</th><th>Stato</th><th>Intervento</th><th>Riprogramma</th></tr></thead><tbody><?php foreach($visite as $v): ?><tr><td><?= (int)$v['numero_visita'] ?></td><td><?= e($v['pianificata_il']?date('d/m/Y H:i',strtotime($v['pianificata_il'])):'Da pianificare') ?></td><td><?= e(ucfirst(str_replace('_',' ',$v['stato']))) ?></td><td><?php if($v['intervento_id']): ?><a href="/app/interventi/<?= (int)$v['intervento_id'] ?>">Apri intervento</a><?php else: ?><?php if($auth->can('contratti','modifica')): ?><form method="post" action="/app/contratti/<?= (int)$contract['id'] ?>/visite/<?= (int)$v['id'] ?>/intervento" class="m-0"><?= $csrf->field() ?><button class="btn btn-sm btn-outline-primary">Crea intervento</button></form><?php endif ?><?php endif ?></td><td><?php if($auth->can('contratti','modifica')): ?><form method="post" action="/app/contratti/<?= (int)$contract['id'] ?>/visite/<?= (int)$v['id'] ?>/ripianifica" class="d-flex flex-wrap gap-2 m-0"><?= $csrf->field() ?><input class="form-control form-control-sm" style="max-width:210px" type="datetime-local" name="pianificata_il" value="<?= $v['pianificata_il']?date('Y-m-d\TH:i',strtotime($v['pianificata_il'])):'' ?>" aria-label="Nuova data per visita <?= (int)$v['numero_visita'] ?>" required><input class="form-control form-control-sm" style="max-width:180px" name="motivo" placeholder="Motivo (facoltativo)" aria-label="Motivo riprogrammazione"><button class="btn btn-sm btn-outline-secondary">Aggiorna data</button></form><?php endif ?><?php if(!empty($storici[$v['id']])): ?><details class="mt-2"><summary class="small text-secondary">Storico modifiche (<?= count($storici[$v['id']]) ?>)</summary><ul class="small mt-1 mb-0"><?php foreach($storici[$v['id']] as $h): ?><li><?= e($h['data_precedente']?date('d/m/Y H:i',strtotime($h['data_precedente'])):'Non pianificata') ?> → <?= e(date('d/m/Y H:i',strtotime($h['data_nuova']))) ?><?= $h['motivo']?' · '.e($h['motivo']):'' ?> · <?= e($h['utente']??'') ?></li><?php endforeach ?></ul></details><?php endif ?></td></tr><?php endforeach ?></tbody></table></div>
